//! Entire immutable old declaration-policy extraction proof.
use crate::lint::Registry;
#[path="../fixtures/original_policies/decl_workspace.rs"]mod original;
#[path="../fixtures/native-decl-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn shared_decl_policy_preserves_entire_original_lifecycle_ancestry_raw_facts_allow_and_reports(){
 for case in fixture::CASES{let root=scratch::dir(&format!("decl-workspace-core-{case}"));for(relative,bytes)in fixture::files(case){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["decl".into()],no_cache:true,raw:true,..Default::default()};let mut old_registry=Registry::default();original::register(&mut old_registry);let old=crate::run::Engine::new(old_registry,options.clone()).unwrap();let mut current_registry=Registry::default();crate::lints::decl::register(&mut current_registry);let current=crate::run::Engine::new(current_registry,options).unwrap();let sem=crate::sem::sem_for(&old.tree).unwrap();assert!(sem.errors.is_empty(),"actual original parsing must succeed: {:?}",sem.errors);let before=old.run_one(old.reg.lints[0].as_ref());let original_scope=old.scopes.for_lint("decl","");assert_eq!(original_scope.exempt("code/probe.dm"),*case=="exempt","the ORIGINAL config loader must observe the intended exemption");if *case=="exempt"{assert!(before.run.sites.is_empty(),"actual immutable original must omit every exempt per-file declaration finding");}if *case=="basic"{assert_eq!(before.run.sites.len(),3,"actual original positive control");}let after=current.run_one(current.reg.lints[0].as_ref());assert_eq!(record(&after),record(&before),"complete original report/ALLOW/status for {case}");println!("SHARED_DECL_WORKSPACE_OLD={}",serde_json::json!({"case":case,"record":record(&before),"source_text":before.run.sites.iter().map(|site|crate::util::normalize_ws(old.tree.get(&site.rel).unwrap().raw().line(site.line as usize))).collect::<Vec<_>>()}));}
}
